51	func initCacheInformers(instance *Store, config *rest.Config, stopCh <-chan struct{}) error {
52		if err := v1alpha1scheme.AddToScheme(scheme.Scheme); err != nil {
53			return err
54		}
55	
56		k8sClientSet, err := kubernetes.NewForConfig(config)
57		if err != nil {
58			return err
59		}
60	
61		crdClientSet, err := v1alpha1.NewForConfig(config)
62		if err != nil {
63			return err
64		}
65	
66		factory := informers.NewSharedInformerFactoryWithOptions(k8sClientSet, 0)
67		crdFactory := crdinformers.NewSharedInformerFactoryWithOptions(crdClientSet, 0)
68	
69		podInformer := factory.Core().V1().Pods().Informer()
70		if _, err := podInformer.AddEventHandler(cache.ResourceEventHandlerFuncs{
71			AddFunc:    instance.addPod,
72			UpdateFunc: instance.updatePod,
73			DeleteFunc: instance.deletePod,
74		}); err != nil {
75			return err
76		}
77	
78		modelInformer := crdFactory.Model().V1alpha1().ModelAdapters().Informer()
79		if _, err = modelInformer.AddEventHandler(cache.ResourceEventHandlerFuncs{
80			AddFunc:    instance.addModelAdapter,
81			UpdateFunc: instance.updateModelAdapter,
82			DeleteFunc: instance.deleteModelAdapter,
83		}); err != nil {
84			return err
85		}
86	
87		factory.Start(stopCh)
88		crdFactory.Start(stopCh)
89	
90		if !cache.WaitForCacheSync(stopCh, podInformer.HasSynced, modelInformer.HasSynced) {
91			return errors.New("timed out waiting for caches to sync")
92		}
93	
94		// After cache sync, resync all ModelAdapters to ensure pod mappings are correct
95		// This handles the case where ModelAdapters were processed before their pods were cached
96		instance.resyncModelAdapters(modelInformer.GetStore(), stopCh)
97	
98		// Log cache state after initialization
99		klog.Infof("Cache initialization completed. Models: %v", instance.ListModels())
100	
101		return nil
102	}
