110	func (c *Store) addPod(obj interface{}) {
111		pod := obj.(*v1.Pod)
112		// Track pods that serve a model either through the standard deployment label
113		// or through ModelClaim runtime annotations.
114		modelName, ok := getModelNameFromPod(pod)
115		modelClaims := utils.ModelClaimBindingsFromPod(pod)
116		if !ok && len(modelClaims) == 0 {
117			klog.V(4).InfoS("ignored pod without model label or annotation", "name", pod.Name)
118			return
119		}
120	
121		// ignore worker pod
122		if isWorkerPod(pod) {
123			return
124		}
125	
126		c.mu.Lock()
127		defer c.mu.Unlock()
128	
129		metaPod := c.addPodLocked(pod)
130		if ok {
131			c.addPodAndModelMappingLocked(metaPod, modelName)
132		}
133		podKey := utils.GeneratePodKey(pod.Namespace, pod.Name)
134		for servedModel, binding := range modelClaims {
135			c.modelClaims.set(podKey, servedModel, binding.Port, binding.State)
136			if binding.Port > 0 {
137				c.addPodAndModelMappingLocked(metaPod, servedModel)
138			}
139		}
140	
141		klog.V(4).Infof("POD CREATED: %s/%s", pod.Namespace, pod.Name)
142		c.debugInfo()
143	
144		// Notify KV event manager
145		if c.kvEventManager != nil {
146			c.kvEventManager.OnPodAdd(pod)
147		}
148	}
