150	func (c *Store) updatePod(oldObj interface{}, newObj interface{}) {
151		oldPod := oldObj.(*v1.Pod)
152		newPod := newObj.(*v1.Pod)
153	
154		// calculate early to avoid unnecessary lock
155		oldIsWorker := isWorkerPod(oldPod)
156		newIsWorker := isWorkerPod(newPod)
157		if oldIsWorker && newIsWorker {
158			klog.InfoS("ignore worker pod update:", "old pod", oldPod.Name, "new pod", newPod.Name)
159			return
160		}
161	
162		_, oldOk := getModelNameFromPod(oldPod)
163		_, existed := c.metaPods.Load(utils.GeneratePodKey(oldPod.Namespace, oldPod.Name)) // Make sure nothing left.
164		newModelName, newOk := getModelNameFromPod(newPod)
165		newModelClaims := utils.ModelClaimBindingsFromPod(newPod)
166	
167		if !oldOk && !existed && !newOk && len(newModelClaims) == 0 {
168			return // No model information to track in either old or new pod
169		}
170	
171		c.mu.Lock()
172		defer c.mu.Unlock()
173	
174		// TODO: No in place update is handled here
175	
176		// Remove old mappings if present, no adapter will be inherited. (Adapters will be rescaned and readded later)
177		if oldOk || existed {
178			odlMetaPod := c.deletePodLocked(oldPod.Name, oldPod.Namespace)
179			if odlMetaPod != nil {
180				for _, modelName := range odlMetaPod.Models.Array() {
181					c.deletePodAndModelMappingLocked(odlMetaPod.Name, odlMetaPod.Namespace, modelName, 1)
182				}
183			}
184			c.modelClaims.clearPod(utils.GeneratePodKey(oldPod.Namespace, oldPod.Name))
185		}
186	
187		// ignore worker pods
188		oldNodeType := oldPod.Labels[nodeType]
189		newNodeType := newPod.Labels[nodeType]
190		if oldNodeType == nodeWorker || newNodeType == nodeWorker {
191			klog.InfoS("ignored ray worker pod", "old pod", oldPod.Name, "new pod", newPod.Name)
192			return
193		}
194	
195		// Add new mappings if present
196		if (newOk || len(newModelClaims) > 0) && !newIsWorker {
197			metaPod := c.addPodLocked(newPod)
198			if newOk {
199				c.addPodAndModelMappingLocked(metaPod, newModelName)
200			}
201			newPodKey := utils.GeneratePodKey(newPod.Namespace, newPod.Name)
202			for servedModel, binding := range newModelClaims {
203				c.modelClaims.set(newPodKey, servedModel, binding.Port, binding.State)
204				if binding.Port > 0 {
205					c.addPodAndModelMappingLocked(metaPod, servedModel)
206				}
207			}
208		}
209	
210		klog.V(4).Infof("POD UPDATED: %s/%s %s", newPod.Namespace, newPod.Name, newPod.Status.Phase)
211		c.debugInfo()
212	
213		// Notify KV event manager
214		if c.kvEventManager != nil {
215			c.kvEventManager.OnPodUpdate(oldPod, newPod)
216		}
217	}
