219	func (c *Store) deletePod(obj interface{}) {
220		var namespace, name string
221		var hasModelInfo bool
222		var pod *v1.Pod
223		switch obj := obj.(type) {
224		case *v1.Pod:
225			pod = obj
226			namespace, name = obj.Namespace, obj.Name
227			_, hasModelInfo = getModelNameFromPod(obj)
228			hasModelInfo = hasModelInfo || len(utils.ModelClaimsFromPod(obj)) > 0
229		case cache.DeletedFinalStateUnknown:
230			if p, ok := obj.Obj.(*v1.Pod); ok {
231				pod = p
232				namespace, name = p.Namespace, p.Name
233				_, hasModelInfo = getModelNameFromPod(p)
234				hasModelInfo = hasModelInfo || len(utils.ModelClaimsFromPod(p)) > 0
235				break
236			}
237	
238			// We can usually ignore cases where the object contained in the tombstone isn't a *v1.Pod. However,
239			// since the following logic in this function still works fine with just the namespace and name,
240			// let's try parsing the tombstone.Key here for added robustness.
241			var err error
242			namespace, name, err = cache.SplitMetaNamespaceKey(obj.Key)
243			if err != nil {
244				klog.ErrorS(err, "couldn't get pod's namespace and name from tombstone", "key", obj.Key)
245				return
246			}
247		}
248		_, existed := c.metaPods.Load(utils.GeneratePodKey(namespace, name))
249		if !hasModelInfo && !existed {
250			return
251		}
252	
253		// Notify KV event manager first (before lock)
254		if c.kvEventManager != nil && pod != nil {
255			c.kvEventManager.OnPodDelete(pod)
256		}
257	
258		c.mu.Lock()
259		defer c.mu.Unlock()
260	
261		// delete base model and associated lora models on this pod
262		metaPod := c.deletePodLocked(name, namespace)
263		if metaPod != nil {
264			for _, modelName := range metaPod.Models.Array() {
265				c.deletePodAndModelMappingLocked(name, namespace, modelName, 1)
266			}
267		}
268		c.modelClaims.clearPod(utils.GeneratePodKey(namespace, name))
269	
270		rateCalculator.PurgeEntriesForPod(name)
271	
272		klog.V(4).Infof("POD DELETED: %s/%s", namespace, name)
273		c.debugInfo()
274	}
