289	func (c *Store) updateModelAdapter(oldObj interface{}, newObj interface{}) {
290		c.mu.Lock()
291		defer c.mu.Unlock()
292	
293		oldModel := oldObj.(*modelv1alpha1.ModelAdapter)
294		newModel := newObj.(*modelv1alpha1.ModelAdapter)
295		for _, pod := range oldModel.Status.Instances {
296			// the namespace of the pod is same as the namespace of model
297			c.deletePodAndModelMappingLocked(pod, oldModel.Namespace, oldModel.Name, 0)
298		}
299	
300		for _, pod := range newModel.Status.Instances {
301			c.addPodAndModelMappingLockedByName(pod, newModel.Namespace, newModel.Name)
302		}
303	
304		c.debugInfo()
