307	func (c *Store) deleteModelAdapter(obj interface{}) {
308		model, ok := obj.(*modelv1alpha1.ModelAdapter)
309		if !ok {
310			tombstone, ok := obj.(cache.DeletedFinalStateUnknown)
311			if !ok {
312				return
313			}
314			model, ok = tombstone.Obj.(*modelv1alpha1.ModelAdapter)
315			if !ok {
316				return
317			}
318		}
319	
320		c.mu.Lock()
321		defer c.mu.Unlock()
322	
323		for _, pod := range model.Status.Instances {
324			// the namespace of the pod is same as the namespace of model
325			c.deletePodAndModelMappingLocked(pod, model.Namespace, model.Name, 0)
326		}
327	
328		c.debugInfo()
