331	func (c *Store) addPodLocked(pod *v1.Pod) *Pod {
332		if c.bufferPod == nil {
333			c.bufferPod = &Pod{
334				Pod:    pod,
335				Models: utils.NewRegistry[string](),
336			}
337		} else {
338			c.bufferPod.Pod = pod
339		}
340		metaPod, loaded := c.metaPods.LoadOrStore(utils.GeneratePodKey(pod.Namespace, pod.Name), c.bufferPod)
341		if !loaded {
342			c.bufferPod = nil
343		}
344		return metaPod
