347	func (c *Store) addPodAndModelMappingLockedByName(podName, namespace, modelName string) {
348		pod, ok := c.metaPods.Load(utils.GeneratePodKey(namespace, podName))
349		if !ok {
350			klog.Errorf("pod %s does not exist in internal-cache", podName)
351			return
352		}
353	
354		c.addPodAndModelMappingLocked(pod, modelName)
355	}
356	
357	func (c *Store) addPodAndModelMappingLocked(metaPod *Pod, modelName string) {
358		if c.bufferModel == nil {
359			c.bufferModel = &Model{
360				Pods:            utils.NewRegistryWithArrayProvider(func(arr []*v1.Pod) *utils.PodArray { return &utils.PodArray{Pods: arr} }),
361				OutputPredictor: NewSimpleOutputPredictor(maxInputTokens, maxOutputTokens, movingWindow),
362			}
363		}
364		metaModel, loaded := c.metaModels.LoadOrStore(modelName, c.bufferModel)
365		if !loaded {
366			c.bufferModel = nil
367			if c.modelRouterProvider != nil {
368				var err error
369				metaModel.QueueRouter, err = c.modelRouterProvider(modelName)
370				if err != nil {
371					klog.Errorf("failed to initialize model-based queue router: %v", err)
372				}
373			}
374			klog.V(4).Infof("MODEL(ADAPTER) CREATED: %s", modelName)
375		}
376	
377		metaPod.Models.Store(modelName, modelName)
378		podKey := utils.GeneratePodKey(metaPod.Namespace, metaPod.Name)
379		metaModel.Pods.Store(podKey, metaPod.Pod)
380	
381		klog.V(4).InfoS("Pod added to model", "model", modelName, "pod", podKey, "pods", metaModel.Pods.Len())
382	}
383	
384	func (c *Store) deletePodLocked(podName, podNamespace string) *Pod {
385		key := utils.GeneratePodKey(podNamespace, podName)
386		metaPod, _ := c.metaPods.LoadAndDelete(key)
387		return metaPod
388	}
389	
390	// deletePodAndModelMapping delete mappings between pods and model by specified names.
391	// If ignoreMapping > 0, podToModel mapping will be ignored.
392	// If ignoreMapping < 0, modelToPod mapping will be ignored
393	func (c *Store) deletePodAndModelMappingLocked(podName, namespace, modelName string, ignoreMapping int) {
394		podKey := utils.GeneratePodKey(namespace, podName)
395		if ignoreMapping <= 0 {
396			if metaPod, ok := c.metaPods.Load(podKey); ok {
397				metaPod.Models.Delete(modelName)
398				// PodToModelMapping entry should only be deleted during pod deleting.
399			}
400		}
401	
402		if ignoreMapping >= 0 {
403			if meta, ok := c.metaModels.Load(modelName); ok {
404				meta.Pods.Delete(podKey)
405				klog.V(4).InfoS("Pod removed from model", "model", modelName, "pod", podKey, "pods", meta.Pods.Len())
406	
407				if meta.Pods.Len() == 0 {
408					c.metaModels.Delete(modelName)
409					klog.V(4).Infof("MODEL(ADAPTER) DELETED: %s", modelName)
410				}
411			}
412		}
413	}
414	
415	// resyncModelAdapters processes all ModelAdapters from the informer store to ensure
416	// all pod mappings are correctly established after cache initialization.
417	// It retries missing pod mappings in batches so startup delay is bounded by
418	// maxRetries * retryInterval regardless of the number of adapters.
419	func (c *Store) resyncModelAdapters(store cache.Store, stopCh <-chan struct{}) {
420		klog.Info("Resyncing ModelAdapters to ensure pod mappings are correct")
421	
422		adapters := make([]*modelv1alpha1.ModelAdapter, 0)
423		for _, obj := range store.List() {
424			if modelAdapter, ok := obj.(*modelv1alpha1.ModelAdapter); ok {
425				adapters = append(adapters, modelAdapter)
426			}
427		}
428	
429		lastMissing := make(map[string][]string)
430		for i := 0; i < modelAdapterResyncMaxRetries; i++ {
431			klog.V(4).Infof("resyncModelAdapters retry attempt %d/%d", i+1, modelAdapterResyncMaxRetries)
432	
433			incompleteModels := 0
434			lastMissing = make(map[string][]string)
435			for _, modelAdapter := range adapters {
436				missingPods := []string{}
437	
438				c.mu.Lock()
439				for _, podName := range modelAdapter.Status.Instances {
440					podKey := utils.GeneratePodKey(modelAdapter.Namespace, podName)
441					if metaPod, exists := c.metaPods.Load(podKey); exists {
442						c.addPodAndModelMappingLocked(metaPod, modelAdapter.Name)
443						klog.V(4).Infof("Resynced pod mapping for adapter %s, pod %s/%s",
444							modelAdapter.Name, modelAdapter.Namespace, podName)
445					} else {
446						missingPods = append(missingPods, podName)
447						klog.V(4).Infof("Pod %s/%s not found in cache for ModelAdapter %s during resync (attempt %d/%d)",
448							modelAdapter.Namespace, podName, modelAdapter.Name, i+1, modelAdapterResyncMaxRetries)
449					}
450				}
451				c.mu.Unlock()
452	
453				if len(missingPods) > 0 {
454					incompleteModels++
455					lastMissing[modelAdapter.Name] = missingPods
456				}
457			}
458	
459			if incompleteModels == 0 {
460				break
461			}
462	
463			if i == modelAdapterResyncMaxRetries-1 {
464				break
465			}
466	
467			if !waitForModelAdapterResyncRetry(stopCh, modelAdapterResyncRetryInterval) {
468				klog.Warning("ModelAdapter resync interrupted by stop signal")
469				return
470			}
471		}
472	
473		totalModels := len(adapters)
474		completeModels := totalModels - len(lastMissing)
475		for _, modelAdapter := range adapters {
476			if missingPods, exists := lastMissing[modelAdapter.Name]; exists {
477				klog.Errorf("Failed to find all pods for ModelAdapter %s after %d retries", modelAdapter.Name, modelAdapterResyncMaxRetries)
478				klog.Errorf("Missing pods for ModelAdapter %s: %v", modelAdapter.Name, missingPods)
479			} else {
480				klog.V(4).Infof("ModelAdapter %s has all pod mappings established", modelAdapter.Name)
481			}
482		}
483		klog.Infof("ModelAdapter mapping resync completed: %d total, %d complete, %d incomplete",
484			totalModels, completeModels, len(lastMissing))
485		klog.Info("ModelAdapter resync completed")
486	}
487	
488	func waitForModelAdapterResyncRetry(stopCh <-chan struct{}, interval time.Duration) bool {
489		if stopCh == nil {
490			time.Sleep(interval)
491			return true
492		}
493	
494		timer := time.NewTimer(interval)
495		defer timer.Stop()
496	
497		select {
498		case <-stopCh:
499			return false
500		case <-timer.C:
501			return true
502		}
503	}
504	
505	func isWorkerPod(pod *v1.Pod) bool {
506		nodeTyp, ok := pod.Labels[nodeType]
507		if ok && nodeTyp == nodeWorker {
508			klog.V(4).InfoS("ignored ray worker pod", "name", pod.Name)
509			return true
510		}
511	
512		pgIndex, ok := pod.Labels[podGroupIndex]
513		if ok {
514			pgIndexNumber, err := strconv.Atoi(pgIndex)
515			if err != nil {
516				klog.V(4).InfoS("ignored pod:", "name", pod.Name, "err", err)
517			}
518			if pgIndexNumber > 0 {
519				klog.V(4).InfoS("ignored pod: podGroupIndex > 0", "name", pod.Name, "index", pgIndex)
520				return true
521			}
522		}
523		return false
524	}
525

