141	// PurgeEntriesForPod removes all history entries whose key starts with podName/.
142	// Call this when a pod is deleted to prevent unbounded map growth in high-churn clusters.
143	func (r *RateCalculator) PurgeEntriesForPod(podName string) {
144		prefix := podName + "/"
145		r.mu.Lock()
146		defer r.mu.Unlock()
147		for k := range r.history {
148			if strings.HasPrefix(k, prefix) {
149				delete(r.history, k)
150			}
151		}
152	}
