154	var (
155		// Global rate calculator instance
156		rateCalculator = &RateCalculator{
157			history:  make(map[string][]MetricSnapshot),
158			maxAge:   5 * time.Minute, // Keep 5 minutes of history
159			maxCount: 20,              // Keep max 20 snapshots per metric
160		}
