167	func initPrometheusAPI(kubeConfig *rest.Config) prometheusv1.API {
168		prometheusEndpoint := utils.LoadEnv("PROMETHEUS_ENDPOINT", "")
169		loadPrometheusBasicAuth(kubeConfig)
170	
171		// Initialize Prometheus API
172		var prometheusApi prometheusv1.API
173		if prometheusEndpoint != "" {
174			api, err := metrics.InitializePrometheusAPI(prometheusEndpoint, prometheusBasicAuthUser, prometheusBasicAuthPass)
175			if err != nil {
176				klog.Errorf("Error initializing Prometheus API: %v", err)
177			} else {
178				prometheusApi = api
179				klog.Infof("Prometheus API initialized successfully")
180			}
181		}
182		return prometheusApi
183	}
