185	// loadPrometheusBasicAuth initializes Prometheus basic auth credentials exactly once (via sync.Once).
186	// It loads from a Kubernetes Secret when PROMETHEUS_BASIC_AUTH_SECRET_NAME is set; otherwise it falls back to env vars.
187	// The resulting values are stored in package-level variables prometheusBasicAuthUser/prometheusBasicAuthPass.
188	func loadPrometheusBasicAuth(kubeConfig *rest.Config) {
189		prometheusBasicAuthOnce.Do(func() {
190			secretName := utils.LoadEnv("PROMETHEUS_BASIC_AUTH_SECRET_NAME", "")
191			if secretName == "" {
192				prometheusBasicAuthUser = utils.LoadEnv("PROMETHEUS_BASIC_AUTH_USERNAME", "")
193				prometheusBasicAuthPass = utils.LoadEnv("PROMETHEUS_BASIC_AUTH_PASSWORD", "")
194				return
195			}
196	
197			secretNamespace := utils.LoadEnv("PROMETHEUS_BASIC_AUTH_SECRET_NAMESPACE", utils.NAMESPACE)
198			// Default to "username" and "password" if keys are not specified
199			usernameKey := utils.LoadEnv("PROMETHEUS_BASIC_AUTH_USERNAME_KEY", "username")
200			passwordKey := utils.LoadEnv("PROMETHEUS_BASIC_AUTH_PASSWORD_KEY", "password")
201	
202			if kubeConfig == nil {
203				klog.Warningf("Prometheus basic auth secret %s/%s is not loaded due to nil kubeConfig", secretNamespace, secretName)
204				return
205			}
206			clientset, err := kubernetes.NewForConfig(kubeConfig)
207			if err != nil {
208				klog.ErrorS(err, "Failed to create Kubernetes client for Prometheus basic auth secret")
209				return
210			}
211	
212			secret, err := clientset.CoreV1().Secrets(secretNamespace).Get(context.Background(), secretName, metav1.GetOptions{})
213			if err != nil {
214				klog.ErrorS(err, "Failed to read Prometheus basic auth secret", "namespace", secretNamespace, "name", secretName)
215				return
216			}
217			if b, ok := secret.Data[usernameKey]; ok {
218				prometheusBasicAuthUser = strings.TrimSpace(string(b))
219			}
220			if b, ok := secret.Data[passwordKey]; ok {
221				prometheusBasicAuthPass = strings.TrimSpace(string(b))
222			}
223		})
224	}
