243	func (c *Store) updatePodMetrics() {
244		c.metaPods.Range(func(key string, metaPod *Pod) bool {
245			if !utils.FilterReadyPod(metaPod.Pod) {
246				// Skip unready pod
247				return true
248			}
249			// Non-blocking send: if the worker pool is saturated (all workers busy
250			// and channel buffer full), skip this pod. It will be retried on the
251			// next refresh cycle (every 50ms). This prevents the metrics refresh
252			// goroutine from blocking indefinitely when workers are stuck on slow
253			// or unreachable engine pods.
254			select {
255			case c.podMetricsJobs <- metaPod:
256			default:
257				klog.V(4).InfoS("Metrics worker pool saturated, skipping pod metrics update",
258					"pod", metaPod.Name)
259			}
260			return true
261		})
262	}
263	
264	func (c *Store) worker(jobs <-chan *Pod) {
265		for pod := range jobs {
266			ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
267			podMetricPort := getPodMetricPort(pod)
268	
269			// Use centralized typed metrics fetcher for better engine abstraction and error handling
270			metricsToFetch := c.getAllAvailableMetrics()
271			endpoint := fmt.Sprintf("%s:%d", pod.Status.PodIP, podMetricPort)
272			engineType := metrics.GetEngineType(*pod.Pod)
273			identifier := pod.Name
274			result, err := c.engineMetricsFetcher.FetchAllTypedMetrics(ctx, endpoint, engineType, identifier, metricsToFetch)
275			if err != nil {
276				klog.V(4).InfoS("Failed to fetch typed metrics from engine pod",
277					"pod", pod.Name, "podIP", pod.Status.PodIP, "port", podMetricPort, "error", err)
278				cancel()
279				continue
280			}
281	
282			for metricName, metricValue := range result.Metrics {
283				sanitizeMetricValueLabels(pod, metricValue)
284				if shouldSkipMetric(pod.Name, metricName) {
285					continue
286				}
287				metrics.EmitMetricToPrometheus(&types.RoutingContext{Model: ""}, pod.Pod, metricName, metricValue, metricValue.GetLabelValues())
288			}
289	
290			for metricName, metricValue := range result.ModelMetrics {
291				sanitizeMetricValueLabels(pod, metricValue)
292				parts := strings.SplitN(metricName, "/", 2)
293				if len(parts) != 2 {
294					continue
295				}
296				model := parts[0]
297				metric := parts[1]
298	
299				model = resolveMetricModelName(pod, model)
300	
301				if shouldSkipMetric(pod.Name, metric) {
302					continue
303				}
304	
305				c.updateThroughputToksPerS(pod, model, metric, metricValue)
306				metrics.EmitMetricToPrometheus(&types.RoutingContext{Model: model}, pod.Pod, metric, metricValue, metricValue.GetLabelValues())
307			}
308			// Update pod metrics using typed results
309			c.updatePodMetricsFromTypedResult(pod, result)
310	
311			c.syncRunningRequestsGlobally(pod)
312	
313			c.updateRealtimeRunningRequestsDrainRate1m(pod)
314	
315			// Handle Prometheus-based metrics separately (these require PromQL queries)
316			if c.prometheusApi != nil {
317				c.enqueuePromQL(pod)
318			} else {
319				klog.V(4).InfoS("Prometheus API not initialized, skipping PromQL metrics", "pod", pod.Name)
320			}
321	
322			// Log successful processing
323			klog.V(5).InfoS("Successfully processed metrics for pod",
324				"pod", pod.Name,
325				"podMetrics", len(result.Metrics),
326				"modelMetrics", len(result.ModelMetrics),
327				"errors", len(result.Errors))
328	
329			cancel()
330		}
331	}
332	
333	func (c *Store) updateMetricFromPromQL(ctx context.Context, pod *Pod) (queryErr error) {
334		podName := pod.Name
335		podMetricPort := getPodMetricPort(pod)
336		for _, metricName := range prometheusMetricNames {
337			queryLabels := map[string]string{
338				"instance": fmt.Sprintf("%s:%d", pod.Status.PodIP, podMetricPort),
339			}
340			metric, ok := metrics.Metrics[metricName]
341			if !ok {
342				klog.V(4).Infof("Cannot find %v in the metric list", metricName)
343				continue
344			}
345			scope := metric.MetricScope
346			if scope == metrics.PodMetricScope {
347				err := c.queryUpdatePromQLMetrics(ctx, metric, queryLabels, pod, "", metricName, podMetricPort)
348				if err != nil {
349					klog.V(4).Infof("Failed to query and update PromQL metrics: %v", err)
350					if queryErr == nil {
351						queryErr = err
352					}
353					continue
354				}
355			} else if scope == metrics.PodModelMetricScope {
356				if pod.Models.Len() > 0 {
357					for _, modelName := range pod.Models.Array() {
358						queryLabels["model_name"] = modelName
359						err := c.queryUpdatePromQLMetrics(ctx, metric, queryLabels, pod, modelName, metricName, podMetricPort)
360						if err != nil {
361							klog.V(4).Infof("Failed to query and update PromQL metrics: %v", err)
362							if queryErr == nil {
363								queryErr = err
364							}
365							continue
366						}
367					}
368				} else {
369					klog.V(4).Infof("Cannot find model names for pod %s", podName)
370				}
371			} else {
372				klog.V(4).Infof("Scope %v is not supported", scope)
373			}
374		}
375		return queryErr
376	}
377	
378	func (c *Store) queryUpdatePromQLMetrics(ctx context.Context, metric metrics.Metric, queryLabels map[string]string, pod *Pod, modelName string, metricName string, podMetricPort int) error {
379		scope := metric.MetricScope
380		query := metrics.BuildQuery(metric.PromQL, queryLabels)
381		// Querying metrics
382		result, warnings, err := c.prometheusApi.Query(ctx, query, time.Now())
383		if err != nil {
384			metrics.EmitMetricToPrometheus(&types.RoutingContext{Model: modelName}, pod.Pod, metrics.PrometheusQueryFail, &metrics.SimpleMetricValue{Value: 1.0}, nil)
385			// Skip this model fetching if an error is thrown
386			return fmt.Errorf("error executing query: %v", err)
387		}
388		if len(warnings) > 0 {
389			klog.V(4).Infof("Warnings: %v\n", warnings)
390		}
391	
392		// Update metrics
393		metricValue := &metrics.PrometheusMetricValue{Result: &result}
394		err = c.updatePodRecord(pod, modelName, metricName, scope, metricValue)
395		if err != nil {
396			return fmt.Errorf("failed to update metrics %s from prometheus %s: %v", metricName, pod.Name, err)
397		}
398		klog.V(5).InfoS("Successfully parsed metrics from prometheus", "metric", metricName, "model", modelName, "PodName", pod.Name, "Port", podMetricPort, "metricValue", metricValue)
399		return nil
400	}
