402	// Update `PodMetrics` and `PodModelMetrics` according to the metric scope
403	// TODO: replace in-place metric update podMetrics and podModelMetrics to fresh copy for preventing stale metric keys
404	func (c *Store) updatePodRecord(pod *Pod, modelName string, metricName string, scope metrics.MetricScope, metricValue metrics.MetricValue) error {
405		if scope == metrics.PodMetricScope {
406			pod.Metrics.Store(metricName, metricValue)
407		} else if scope == metrics.PodModelMetricScope {
408			if modelName == "" {
409				var ok bool
410				modelName, ok = constants.ModelNameFromMetadata(pod.Labels, pod.Annotations)
411				if !ok {
412					return fmt.Errorf("modelName should not be empty for scope %v", scope)
413				}
414			}
415			pod.ModelMetrics.Store(c.getPodModelMetricName(modelName, metricName), metricValue)
416		} else {
417			return fmt.Errorf("scope %v is not supported", scope)
418		}
419		return nil
420	}
