441	// updateModelReplicaMetrics emits model_replicas=1 for each ready, routable engine pod and
442	// removes stale series when pods leave the cache.
443	func (c *Store) updateModelReplicaMetrics() {
444		active := make(map[string]struct{})
445	
446		c.metaPods.Range(func(key string, metaPod *Pod) bool {
447			pod := metaPod.Pod
448			if pod == nil || !utils.FilterReadyPod(pod) || !isPodWithHTTPServer(pod) {
449				return true
450			}
451	
452			modelName, ok := getModelNameFromPod(pod)
453			if !ok || modelName == "" {
454				return true
455			}
456	
457			extras := map[string]string{"model_name": modelName}
458			metrics.EmitMetricToPrometheus(
459				&types.RoutingContext{Model: modelName},
460				pod,
461				metrics.ModelReplicas,
462				&metrics.SimpleMetricValue{Value: 1.0},
463				extras,
464			)
465			c.modelReplicaEmitted.Store(key, modelReplicaState{pod: pod, modelName: modelName})
466			active[key] = struct{}{}
467			return true
468		})
469	
470		c.modelReplicaEmitted.Range(func(key string, state modelReplicaState) bool {
471			if _, ok := active[key]; ok {
472				return true
473			}
474			extras := map[string]string{"model_name": state.modelName}
475			metrics.DeleteGaugeMetricForPod(
476				metrics.ModelReplicas,
477				&types.RoutingContext{Model: state.modelName},
478				state.pod,
479				extras,
480			)
481			c.modelReplicaEmitted.Delete(key)
482			return true
483		})
484	}
