509	// updateThroughputToksPerS derives a per-second token throughput rate from a cumulative token counter
510	// and stores it under AvgPromptThroughputToksPerS (prefill pods) or AvgGenerationThroughputToksPerS
511	// (decode pods). No-ops for pods that don't match either role or metric name.
512	func (c *Store) updateThroughputToksPerS(pod *Pod, model, metric string, metricValue metrics.MetricValue) {
513		var rateMetricName string
514		if strings.Contains(pod.Name, "prefill") && metric == metrics.PromptTokenTotal {
515			rateMetricName = metrics.AvgPromptThroughputToksPerS
516		} else if strings.Contains(pod.Name, "decode") && metric == metrics.GenerationTokenTotal {
517			rateMetricName = metrics.AvgGenerationThroughputToksPerS
518		}
519		if rateMetricName == "" {
520			return
521		}
522		perSecRate := c.calculatePerSecondRate(pod, model, metric, metricValue.GetSimpleValue())
523		if perSecRate >= 0 {
524			rateValue := &metrics.SimpleMetricValue{Value: perSecRate}
525			metrics.EmitMetricToPrometheus(&types.RoutingContext{Model: model}, pod.Pod, rateMetricName, rateValue, metricValue.GetLabelValues())
526			_ = c.updatePodRecord(pod, model, rateMetricName, metrics.PodModelMetricScope, rateValue)
527			klog.V(4).InfoS("get metric per sec rate", "metric", rateMetricName, "raw_value", metricValue.GetSimpleValue(), "per_sec_rate", rateValue.GetSimpleValue())
528		}
529	}
530	
531	// syncRunningRequestsGlobally computes the cross-gateway running request count for a pod and
532	// stores it so GetMetricValueByPod returns the global total. It reads the in-memory snapshot
533	// cache (populated every 100ms by initGatewaySnapshotSync — no Redis call here), sums
534	// requests_running from all other gateway instances, then adds this gateway's own local
535	// atomic counter (always fresher than the Redis snapshot for the local instance).
536	func (c *Store) syncRunningRequestsGlobally(pod *Pod) {
537		raw := c.gatewaySnapshotCache.Load()
538		if raw == nil {
539			return
540		}
541		snapshotCache := raw.(map[string][]map[string]string)
542	
543		var remoteRunning float64
544		podKey := utils.GeneratePodKey(pod.Namespace, pod.Name)
545		for _, fields := range snapshotCache[podKey] {
546			if fields["gateway_instance_id"] == gatewayPodName {
547				continue
548			}
549			running, _ := strconv.ParseFloat(fields["requests_running"], 64)
550			remoteRunning += running
551		}
552	
553		localRunning := float64(atomic.LoadInt32(&pod.runningRequests))
554		total := localRunning + remoteRunning
555		klog.V(5).InfoS("running requests aggregation", "pod", pod.Name, "local", localRunning, "remote", remoteRunning, "total", total)
556	
557		totalValue := &metrics.SimpleMetricValue{Value: total}
558		metrics.EmitMetricToPrometheus(&types.RoutingContext{}, pod.Pod, metrics.RealtimeNumRequestsRunning, totalValue, nil)
559		if err := c.updatePodRecord(pod, "", metrics.RealtimeNumRequestsRunning,
560			metrics.PodMetricScope, totalValue); err != nil {
561			klog.V(4).ErrorS(err, "failed to update global running requests", "pod", pod.Name)
562		}
563	}
564	
565	// updateRealtimeRunningRequestsDrainRate1m computes the 1-minute rolling rate at which completed
566	// requests are draining on decode pods and stores it under RealtimeRunningRequestsDrainRate1m.
567	// Only applies to decode pods; no-ops for all others.
568	func (c *Store) updateRealtimeRunningRequestsDrainRate1m(pod *Pod) {
569		if !strings.Contains(pod.Name, "decode") {
570			return
571		}
572		completed := float64(atomic.LoadInt64(&pod.completedRequests))
573		drainRate := c.calculateRate1m(pod, "completed_requests", completed)
574		if drainRate >= 0 {
575			rateValue := &metrics.SimpleMetricValue{Value: drainRate}
576			metrics.EmitMetricToPrometheus(&types.RoutingContext{}, pod.Pod, metrics.RealtimeRunningRequestsDrainRate1m, rateValue, nil)
577			_ = c.updatePodRecord(pod, "", metrics.RealtimeRunningRequestsDrainRate1m, metrics.PodMetricScope, rateValue)
578			klog.V(4).InfoS("Updating drain rate metric", "pod", pod.Name,
579				"completed_requests", completed, metrics.RealtimeRunningRequestsDrainRate1m, drainRate)
580		}
581	}
582	
583	// updatePodMetricsFromTypedResult processes the typed metrics result and updates pod storage.
584	// Precondition: labels in result must already be sanitized via sanitizeMetricValueLabels.
585	// The production caller worker() sanitizes every MetricValue in result before invoking this
586	// function, so labels stored in pod.Metrics / pod.ModelMetrics carry resolved model_name /
587	// engine_type values rather than the "undefined" sentinel emitted by some engines (e.g. trtllm).
588	func (c *Store) updatePodMetricsFromTypedResult(pod *Pod, result *metrics.EngineMetricsResult) {
589		// Process pod-scoped metrics
590		for metricName, metricValue := range result.Metrics {
591			if metricDef, exists := metrics.Metrics[metricName]; exists {
592				err := c.updatePodRecord(pod, "", metricName, metricDef.MetricScope, metricValue)
593				if err != nil {
594					klog.V(4).InfoS("Failed to update pod metric",
595						"pod", pod.Name, "metric", metricName, "error", err)
596				}
597			}
598		}
599	
600		// Process model-scoped metrics
601		for modelMetricKey, metricValue := range result.ModelMetrics {
602			// modelMetricKey format: "model/metric"
603			modelName, metricName := parseModelMetricKey(modelMetricKey)
604	
605			modelName = resolveMetricModelName(pod, modelName)
606	
607			if metricDef, exists := metrics.Metrics[metricName]; exists {
608				err := c.updatePodRecord(pod, modelName, metricName, metricDef.MetricScope, metricValue)
609				if err != nil {
610					klog.V(4).InfoS("Failed to update model metric",
611						"pod", pod.Name, "model", modelName, "metric", metricName, "error", err)
612				}
613			}
614		}
615	
616		// Log any errors from the fetching process
617		for _, err := range result.Errors {
618			klog.V(4).InfoS("Metric fetching error", "pod", pod.Name, "error", err)
619		}
620	}
621	
622	// parseModelMetricKey parses a key like "model/metric" into model name and metric name
623	func parseModelMetricKey(key string) (modelName, metricName string) {
624		separator := strings.LastIndexByte(key, '/')
625		if separator < 0 {
626			return "", key // Fallback if parsing fails
627		}
628		return key[:separator], key[separator+1:]
629	}
630	
631	func resolveMetricModelName(pod *Pod, modelName string) string {
632		if !isUndefinedMetricLabelValue(modelName) {
633			return modelName
634		}
635	
636		if podModel, ok := constants.ModelNameFromMetadata(pod.Labels, pod.Annotations); ok {
637			klog.V(4).InfoS("Using pod metadata as model name fallback",
638				"pod", pod.Name, "originalModel", modelName, "resolvedModel", podModel)
639			return podModel
640		}
641	
642		return modelName
643	}
644	
645	func resolveMetricEngineType(pod *Pod, engineType string) string {
646		if !isUndefinedMetricLabelValue(engineType) {
647			return engineType
648		}
649	
650		if podEngine, err := getPodLabel(pod, engineLabel); err == nil && podEngine != "" {
651			klog.V(4).InfoS("Using pod label as engine type fallback",
652				"pod", pod.Name, "originalEngineType", engineType, "resolvedEngineType", podEngine)
653			return podEngine
654		}
655	
656		return engineType
657	}
658	
659	func sanitizeMetricValueLabels(pod *Pod, metricValue metrics.MetricValue) {
660		switch value := metricValue.(type) {
661		case *metrics.SimpleMetricValue:
662			value.Labels = sanitizeMetricLabels(pod, value.Labels)
663		case *metrics.HistogramMetricValue:
664			value.Labels = sanitizeMetricLabels(pod, value.Labels)
665		}
666	}
667	
668	func sanitizeMetricLabels(pod *Pod, labelValues map[string]string) map[string]string {
669		if len(labelValues) == 0 {
670			return labelValues
671		}
672	
673		// Key-existence check is required: isUndefinedMetricLabelValue("") is true, so a missing
674		// key would otherwise falsely trigger the alloc path even though we never add it back.
675		modelVal, hasModel := labelValues["model_name"]
676		engineVal, hasEngine := labelValues["engine_type"]
677		modelNeedsFix := hasModel && isUndefinedMetricLabelValue(modelVal)
678		engineNeedsFix := hasEngine && isUndefinedMetricLabelValue(engineVal)
679	
680		if !modelNeedsFix && !engineNeedsFix {
681			return labelValues
682		}
683	
684		sanitized := make(map[string]string, len(labelValues))
685		for key, value := range labelValues {
686			sanitized[key] = value
687		}
688		if modelNeedsFix {
689			sanitized["model_name"] = resolveMetricModelName(pod, modelVal)
690		}
691		if engineNeedsFix {
692			sanitized["engine_type"] = resolveMetricEngineType(pod, engineVal)
693		}
694	
695		return sanitized
696	}
697	
698	func isUndefinedMetricLabelValue(value string) bool {
699		return value == "" || value == undefinedMetricLabelValue
700	}
